// Package sts implements the minimal security-token-service mint used by
// the marketplace access-token endpoint (plan 016; full plan 008 approvals
// endpoint is separate scope). Tickets are gateway-signed JWTs with an
// audit row in the tickets store — no payload content, ever.
package sts

import (
	"crypto/ed25519"
	"time"

	"github.com/golang-jwt/jwt/v5"
	"github.com/google/uuid"

	"github.com/konsulin-care/konsulin-gateway/pkg/keys"
)

// MaxTicketTTL caps ticket lifetimes (plan 008 §2: TTL ≤ 900s).
const MaxTicketTTL = 15 * time.Minute

// Request describes the ticket to mint. All fields become claims.
type Request struct {
	Aud     string
	Sub     string
	Scope   string
	Purpose string
	TTL     time.Duration
}

// Ticket is a freshly minted STS ticket.
type Ticket struct {
	Token     string
	JTI       string
	ExpiresAt time.Time
}

// Mint signs a gateway STS ticket: iss=gateway, aud, sub, scope, purpose,
// jti, iat, exp (TTL clamped to (0, MaxTicketTTL]), EdDSA with the kid
// header set to the signing key's RFC 7638 thumbprint — verifiers fetch
// it from /.well-known/jwks.
func Mint(priv ed25519.PrivateKey, req Request) (*Ticket, error) {
	ttl := req.TTL
	if ttl <= 0 || ttl > MaxTicketTTL {
		ttl = MaxTicketTTL
	}
	jti := uuid.New().String()
	now := time.Now()
	claims := jwt.MapClaims{
		"iss":     "gateway",
		"aud":     req.Aud,
		"sub":     req.Sub,
		"scope":   req.Scope,
		"purpose": req.Purpose,
		"jti":     jti,
		"iat":     now.Unix(),
		"exp":     now.Add(ttl).Unix(),
	}
	tok := jwt.NewWithClaims(&jwt.SigningMethodEd25519{}, claims)
	tok.Header["kid"] = keys.JWKThumbprint(priv.Public().(ed25519.PublicKey))
	token, err := tok.SignedString(priv)
	if err != nil {
		return nil, err
	}
	return &Ticket{Token: token, JTI: jti, ExpiresAt: now.Add(ttl)}, nil
}

// Package health provides party health probing (plan 006): on-demand
// verification of a party's registered endpoints.health URL before tickets
// are minted or webhooks are considered deliverable. No caching, no
// background job, no in-probe retry — one probe, one verdict, fail closed.
package health

import (
	"context"
	"time"

	"github.com/konsulin-care/konsulin-gateway/internal/app/contracts"
	gatewayerrors "github.com/konsulin-care/konsulin-gateway/pkg/errors"
)

// Party states mirrored from the registry service.
const (
	statePending = "pending"
	stateActive  = "active"
	stateRevoked = "revoked"
)

// Probe outcome values — PartyHealth.Status and audit meta outcome.
const (
	StatusHealthy   = "healthy"
	StatusUnhealthy = "unhealthy"
)

// auditAction is the metadata-only audit action recorded per probe attempt
// (security invariant 6: metadata only — action + outcome, no payloads).
const auditAction = "party-health-probe"

// Service probes party health endpoints on demand (plan 006).
type Service struct {
	partyRepo contracts.PartyRepository
	prober    contracts.HealthProber
	auditRepo contracts.AuditRepository
}

// NewService creates a health Service. prober and auditRepo are injected at
// the composition root.
func NewService(
	partyRepo contracts.PartyRepository,
	prober contracts.HealthProber,
	auditRepo contracts.AuditRepository,
) *Service {
	return &Service{partyRepo: partyRepo, prober: prober, auditRepo: auditRepo}
}

// ProbeParty probes the party's registered endpoints.health URL. Unknown
// party → 404 GW-PARTY-001; non-active (pending/revoked) → 403
// GW-PARTY-002; missing/non-string endpoints.health or a failed probe →
// 502 GW-PARTY-009 (unhealthy, fail closed). Success → healthy result with
// checked_at. Every probe attempt that passes the state checks writes
// exactly one metadata-only audit entry.
func (s *Service) ProbeParty(ctx context.Context, partyID string) (*contracts.PartyHealth, error) {
	party, err := s.partyRepo.GetByID(ctx, partyID)
	if err != nil {
		return nil, err
	}
	if party == nil {
		return nil, &gatewayerrors.DomainError{
			Code:       gatewayerrors.CodePartyNotFound,
			Message:    "party not found",
			HTTPStatus: 404,
		}
	}
	if party.State != stateActive {
		return nil, &gatewayerrors.DomainError{
			Code:       gatewayerrors.CodePartyNotActive,
			Message:    "party is not active",
			HTTPStatus: 403,
		}
	}

	healthURL, ok := party.Endpoints["health"].(string)
	if !ok || healthURL == "" {
		return nil, s.unhealthy(ctx, partyID)
	}
	if err := s.prober.Probe(ctx, healthURL); err != nil {
		return nil, s.unhealthy(ctx, partyID)
	}

	_ = s.auditRepo.Log(ctx, partyID, auditAction, partyID, map[string]interface{}{
		"outcome": StatusHealthy,
	})
	return &contracts.PartyHealth{PartyID: partyID, Status: StatusHealthy, CheckedAt: time.Now()}, nil
}

// unhealthy audits the failed probe attempt and returns the fail-closed
// domain error (GW-PARTY-009, 502).
func (s *Service) unhealthy(ctx context.Context, partyID string) *gatewayerrors.DomainError {
	_ = s.auditRepo.Log(ctx, partyID, auditAction, partyID, map[string]interface{}{
		"outcome": StatusUnhealthy,
	})
	return &gatewayerrors.DomainError{
		Code:       gatewayerrors.CodePartyUnhealthy,
		Message:    "party health probe failed",
		HTTPStatus: 502,
	}
}

package contracts

import (
	"context"
)

// Ticket outcomes.
const (
	TicketOutcomePending = "pending"
	TicketOutcomeUsed    = "used"
)

// Ticket is one minted STS ticket audit record (plan 008 §4, minimal).
// No payload content is ever stored — routing metadata only.
type Ticket struct {
	JTI     string
	PartyID string
	Aud     string
	Scope   string
	Purpose string
	Iat     int64
	Exp     int64
	Outcome string
}

// TicketRepository manages minted-ticket audit records.
type TicketRepository interface {
	// Record stores a minted ticket with outcome=pending.
	Record(ctx context.Context, t *Ticket) error
	// UseJTI atomically marks a pending ticket used. Returns false when
	// the jti is unknown or already used (replay detection).
	UseJTI(ctx context.Context, jti string) (bool, error)
	// GetByPurpose returns the most recent pending, unexpired ticket with
	// the given scope+purpose (result-ticket reuse across delivery
	// attempts), or nil when none qualifies.
	GetPendingByScopePurpose(ctx context.Context, scope, purpose string, now int64) (*Ticket, error)
}

package sqlite

import (
	"context"
	"database/sql"
	"errors"

	"github.com/konsulin-care/konsulin-gateway/internal/app/contracts"
)

// TicketsRepo implements contracts.TicketRepository using SQLite.
type TicketsRepo struct {
	db *sql.DB
}

// NewTicketsRepo creates a new TicketsRepo.
func NewTicketsRepo(db *sql.DB) *TicketsRepo {
	return &TicketsRepo{db: db}
}

// Record stores a minted ticket with outcome=pending.
func (r *TicketsRepo) Record(ctx context.Context, t *contracts.Ticket) error {
	_, err := r.db.ExecContext(ctx,
		`INSERT INTO tickets (jti, party_id, aud, scope, purpose, iat, exp, outcome)
		 VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
		t.JTI, t.PartyID, t.Aud, t.Scope, t.Purpose, t.Iat, t.Exp, contracts.TicketOutcomePending,
	)
	return err
}

// UseJTI atomically marks a pending ticket used. Returns false when the
// jti is unknown or already used (replay detection, ADR-017).
func (r *TicketsRepo) UseJTI(ctx context.Context, jti string) (bool, error) {
	result, err := r.db.ExecContext(ctx,
		"UPDATE tickets SET outcome = 'used' WHERE jti = ? AND outcome = 'pending'",
		jti,
	)
	if err != nil {
		return false, err
	}
	rows, err := result.RowsAffected()
	if err != nil {
		return false, err
	}
	return rows > 0, nil
}

// GetPendingByScopePurpose returns the most recent pending, unexpired
// ticket with the given scope+purpose, or nil when none qualifies.
func (r *TicketsRepo) GetPendingByScopePurpose(ctx context.Context, scope, purpose string, now int64) (*contracts.Ticket, error) {
	var tk contracts.Ticket
	err := r.db.QueryRowContext(ctx,
		`SELECT jti, party_id, aud, scope, purpose, iat, exp, outcome FROM tickets
		 WHERE scope = ? AND purpose = ? AND outcome = 'pending' AND exp > ?
		 ORDER BY iat DESC LIMIT 1`,
		scope, purpose, now,
	).Scan(&tk.JTI, &tk.PartyID, &tk.Aud, &tk.Scope, &tk.Purpose, &tk.Iat, &tk.Exp, &tk.Outcome)
	if errors.Is(err, sql.ErrNoRows) {
		return nil, nil
	}
	if err != nil {
		return nil, err
	}
	return &tk, nil
}

package http

import (
	"crypto/ed25519"
	"fmt"
	"net/http"

	"github.com/go-chi/chi/v5"

	"github.com/konsulin-care/konsulin-gateway/internal/app/contracts"
	gatewayerrors "github.com/konsulin-care/konsulin-gateway/pkg/errors"
	"github.com/konsulin-care/konsulin-gateway/pkg/keys"
)

// PartyJWKSHandler serves GET /v1/parties/{id}/jwks (plan 005 §3): the
// party's currently-valid keys — active plus grace-window — as an RFC 7517
// JWK Set. Public endpoint: verifiers must be able to fetch keys before
// they hold any party credential.
type PartyJWKSHandler struct {
	registryService RegistryService
}

// NewPartyJWKSHandler creates a PartyJWKSHandler over the registry service.
func NewPartyJWKSHandler(registryService RegistryService) *PartyJWKSHandler {
	return &PartyJWKSHandler{registryService: registryService}
}

// PartyJWKS handles GET /v1/parties/{id}/jwks. 404 (GW-PARTY-001) when the
// party is unknown or revoked — a revoked party's trusted key set no longer
// exists; an empty keys array is never served. JWK shape is dispatched on
// the stored key-row algorithm (Ed25519 → OKP, ES256 → EC P-256); unknown
// stored algorithm or malformed key material fails closed with 500 rather
// than emitting a partial JWKS.
func (h *PartyJWKSHandler) PartyJWKS(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Cache-Control", "no-store")

	validKeys, err := h.registryService.GetPartyJWKS(r.Context(), chi.URLParam(r, "id"))
	if err != nil {
		writeError(w, r, err)
		return
	}

	jwkSet := make([]map[string]string, 0, len(validKeys))
	for _, k := range validKeys {
		jwk, jerr := partyJWK(k)
		if jerr != nil {
			writeError(w, r, &gatewayerrors.DomainError{
				Code:       gatewayerrors.CodeInternal,
				Message:    "stored key material invalid",
				HTTPStatus: http.StatusInternalServerError,
			})
			return
		}
		jwkSet = append(jwkSet, jwk)
	}
	writeJSON(w, http.StatusOK, map[string]interface{}{"keys": jwkSet})
}

// partyJWK builds the RFC 7517 JWK for a stored key row, dispatching on the
// row's algorithm: Ed25519 → OKP/Ed25519, ES256 → EC/P-256. Unknown
// algorithms and unparseable key material return an error (fail closed).
func partyJWK(k *contracts.PartyKey) (map[string]string, error) {
	switch k.Algorithm {
	case "Ed25519":
		pub, err := keys.ParseEd25519PublicKey(k.PublicKey)
		if err != nil {
			return nil, err
		}
		return keys.Ed25519JWK(k.Kid, pub), nil
	case "ES256":
		pub, err := keys.ParseES256PublicKey(k.PublicKey)
		if err != nil {
			return nil, err
		}
		return keys.ES256JWK(k.Kid, pub), nil
	default:
		return nil, fmt.Errorf("unsupported stored key algorithm %q", k.Algorithm)
	}
}

// GatewayJWKSHandler serves GET /.well-known/jwks (plan 005 §4/§5): the
// current gateway signing key as an RFC 7517 JWK Set, kid versioned by RFC
// 7638 thumbprint. Built once at the composition root from config; rotation
// is an ops env swap + restart — the old key vanishes immediately (no
// gateway-key grace window), so verifiers must refetch on unknown kid.
type GatewayJWKSHandler struct {
	jwk map[string]string
}

// NewGatewayJWKSHandler creates a GatewayJWKSHandler for the given gateway
// signing public key; the kid is derived as its RFC 7638 thumbprint.
func NewGatewayJWKSHandler(pub ed25519.PublicKey) *GatewayJWKSHandler {
	return &GatewayJWKSHandler{jwk: keys.Ed25519JWK(keys.JWKThumbprint(pub), pub)}
}

// GatewayJWKS handles GET /.well-known/jwks — public, always 200 with the
// single current gateway key.
func (h *GatewayJWKSHandler) GatewayJWKS(w http.ResponseWriter, _ *http.Request) {
	w.Header().Set("Cache-Control", "no-store")
	writeJSON(w, http.StatusOK, map[string]interface{}{
		"keys": []map[string]string{h.jwk},
	})
}

package main

import (
	"context"
	"crypto/ed25519"
	"database/sql"
	"fmt"
	"net/http"
	"time"

	"github.com/go-chi/chi/v5"
	"go.uber.org/zap"

	apphttp "github.com/konsulin-care/konsulin-gateway/internal/app/delivery/http"
	healthdriver "github.com/konsulin-care/konsulin-gateway/internal/app/drivers/health"
	"github.com/konsulin-care/konsulin-gateway/internal/app/drivers/payment"
	"github.com/konsulin-care/konsulin-gateway/internal/app/drivers/payment/xendit"
	"github.com/konsulin-care/konsulin-gateway/internal/app/drivers/sqlite"
	"github.com/konsulin-care/konsulin-gateway/internal/app/services/admin"
	"github.com/konsulin-care/konsulin-gateway/internal/app/services/health"
	"github.com/konsulin-care/konsulin-gateway/internal/app/services/identity"
	"github.com/konsulin-care/konsulin-gateway/internal/app/services/listings"
	"github.com/konsulin-care/konsulin-gateway/internal/app/services/payments"
	"github.com/konsulin-care/konsulin-gateway/internal/app/services/registry"
	"github.com/konsulin-care/konsulin-gateway/internal/app/services/webhooks"
	deliveryhttp "github.com/konsulin-care/konsulin-gateway/internal/delivery/http"
	"github.com/konsulin-care/konsulin-gateway/pkg/config"
	"github.com/konsulin-care/konsulin-gateway/pkg/keys"
	"github.com/konsulin-care/konsulin-gateway/pkg/middleware"
)

// newRouter builds the chi mux, background workers' dependencies, and the
// workers themselves. Returns the expiry sweeper (plan 009 §3) and the
// webhook delivery worker (plan 007 amendment) for composition-root start.
func newRouter(log *zap.Logger, db *sql.DB, cfg *config.Config) (*chi.Mux, *payments.Sweeper, *webhooks.Worker, error) {
	r := chi.NewRouter()

	// Middleware chain
	r.Use(middleware.Recovery(log))
	r.Use(middleware.RequestID)
	r.Use(middleware.Logger(log))
	r.Use(middleware.Idempotency(db))

	// Initialize repositories
	tokenRepo := sqlite.NewBootstrapTokenRepo(db)
	partyRepo := sqlite.NewPartyRepo(db)
	keyRepo := sqlite.NewPartyKeyRepo(db)
	auditRepo := sqlite.NewAuditRepo(db)
	identityRepo := sqlite.NewIdentityRepo(db)
	linkRepo := sqlite.NewLinkRepo(db)
	paymentsRepo := sqlite.NewPaymentsRepo(db)
	listingsRepo := sqlite.NewListingsRepo(db)
	outboxRepo := sqlite.NewWebhookOutboxRepo(db)
	ticketsRepo := sqlite.NewTicketsRepo(db)

	// Parse bootstrap token TTL
	bootstrapTokenTTL, err := time.ParseDuration(cfg.BootstrapTokenTTL)
	if err != nil {
		bootstrapTokenTTL = 24 * time.Hour
	}

	// Parse key grace window (plan 005): how long a superseded party key
	// stays in the JWKS and remains valid for auth after rotation.
	keyGraceWindow, err := time.ParseDuration(cfg.KeyGraceWindow)
	if err != nil {
		keyGraceWindow = 10 * time.Minute
	}

	// Parse admin signing key once; typed keys flow to services and middleware.
	adminPrivKey, err := keys.ParseEd25519PrivateKey(cfg.AdminSigningKey)
	if err != nil {
		return nil, nil, nil, fmt.Errorf("admin signing key invalid: %w", err)
	}

	// Parse gateway signing key once; its RFC 7638 thumbprint kid feeds the
	// public JWKS endpoint (plan 005 §5). Rotation = ops env swap + restart.
	gatewayPrivKey, err := keys.ParseEd25519PrivateKey(cfg.GatewaySigningKey)
	if err != nil {
		return nil, nil, nil, fmt.Errorf("gateway signing key invalid: %w", err)
	}

	// Initialize services
	authService := admin.NewAuthService(cfg.OperatorCredentials, adminPrivKey, auditRepo)
	registryService := registry.NewService(tokenRepo, partyRepo, keyRepo, auditRepo, bootstrapTokenTTL, keyGraceWindow)
	identityService := identity.NewService(identityRepo, linkRepo, partyRepo, auditRepo)

	// Plan 006: party health probe — on-demand verification of a party's
	// registered endpoints.health URL. Single attempt, fail closed; the
	// prober refuses redirects and non-http(s) schemes (SSRF hardening).
	// Timeout from config (APP_HEALTH_PROBE_TIMEOUT, default 5s).
	healthProbeTimeout, err := time.ParseDuration(cfg.HealthProbeTimeout)
	if err != nil {
		healthProbeTimeout = 5 * time.Second
	}
	healthProber := healthdriver.NewProber(&http.Client{Timeout: healthProbeTimeout})
	healthService := health.NewService(partyRepo, healthProber, auditRepo)

	// Money plane: provider built at the composition root; the verification
	// registry dispatches by declared header presence (no if/else in layers
	// above). Provider selection is constructor injection — no init(), no
	// global registry (repo rule). Swap providers by editing this line.
	// Settlement notifications (provider + buyer) and the plan-016
	// access-token mint ride the webhook outbox + gateway signing key.
	xenditProvider := xendit.NewProvider(&http.Client{Timeout: 15 * time.Second}, "", cfg.XenditToken)
	paymentRegistry := payment.NewRegistry(xenditProvider.CallbackSchemes()...)
	paymentsService := payments.NewService(payments.Options{
		Provider: xenditProvider, Registry: paymentRegistry, CallbackKey: []byte(cfg.XenditCallbackToken),
		Payments: paymentsRepo, Listings: listingsRepo, Parties: partyRepo,
		Outbox: outboxRepo, Tickets: ticketsRepo, Audit: auditRepo, GatewayPriv: gatewayPrivKey,
	})

	// Integration plane (plan 007 amendment / plan 017): marketplace-gated
	// invocation. Signer kid = gateway JWKS thumbprint; the rate limiter is
	// in-memory fixed-window (no Redis — single-node invariant, plan 010).
	webhookSigner := webhooks.NewSigner(gatewayPrivKey)
	rateLimiter := webhooks.NewLimiter(cfg.RateLimitMax, parseDur(cfg.RateLimitWindow, time.Minute))
	webhooksService := webhooks.NewService(webhooks.Options{
		Outbox: outboxRepo, Parties: partyRepo, Listings: listingsRepo, Payments: paymentsRepo,
		Tickets: ticketsRepo, Audit: auditRepo, Signer: webhookSigner, Limiter: rateLimiter,
		MaxAttempts: cfg.WebhookMaxAttempts,
		BackoffBase: parseDur(cfg.WebhookBackoffBase, webhooks.DefaultBackoffBase),
		SyncTimeout: parseDur(cfg.WebhookSyncTimeout, webhooks.DefaultSyncTimeout),
		ResultTTL:   parseDur(cfg.WebhookResultTTL, webhooks.DefaultResultTTL),
		DeliveryTTL: webhooks.DefaultDeliveryTTL,
	})
	webhooksWorker := webhooks.NewWorker(webhooks.WorkerDeps{
		Outbox: outboxRepo, Tickets: ticketsRepo, Audit: auditRepo,
		Signer: webhookSigner, Limiter: rateLimiter,
		ResolveBody: webhooksService.ResolveBody, ForgetBody: webhooksService.ForgetBody,
		Logger: log,
	}, webhooks.WorkerConfig{
		Interval:        parseDur(cfg.WebhookPollInterval, webhooks.DefaultWorkerInterval),
		Batch:           webhooks.DefaultWorkerBatch,
		Workers:         cfg.WebhookWorkers,
		MaxAttempts:     cfg.WebhookMaxAttempts,
		BackoffBase:     parseDur(cfg.WebhookBackoffBase, webhooks.DefaultBackoffBase),
		ResultTTL:       parseDur(cfg.WebhookResultTTL, webhooks.DefaultResultTTL),
		DeliveryTimeout: parseDur(cfg.WebhookDeliveryTimeout, webhooks.DefaultDeliveryTimeout),
	})

	// Initialize handlers
	partiesHandler := apphttp.NewPartiesHandler(registryService, healthService)
	partyJWKSHandler := apphttp.NewPartyJWKSHandler(registryService)
	gatewayJWKSHandler := apphttp.NewGatewayJWKSHandler(gatewayPrivKey.Public().(ed25519.PublicKey))
	adminHandler := apphttp.NewAdminHandler(authService, registryService)
	identitiesHandler := apphttp.NewIdentitiesHandler(identityService)
	paymentsHandler := apphttp.NewPaymentsHandler(paymentsService)

	// Party auth (plan 009 §0): EdDSA JWT by kid → party_keys lookup, then
	// active-party state check. Resolvers adapt the repos at the composition
	// root; the middleware itself stays dependency-free.
	keyLookup := func(ctx context.Context, kid string) (string, string, string, error) {
		k, err := keyRepo.GetByKid(ctx, kid)
		if err != nil || k == nil {
			return "", "", "", err
		}
		return k.PartyID, k.PublicKey, k.Algorithm, nil
	}
	partyAuth := middleware.PartyAuth(
		keyLookup,
		func(ctx context.Context, partyID string) (string, error) {
			p, err := partyRepo.GetByID(ctx, partyID)
			if err != nil || p == nil {
				return "", err
			}
			return p.State, nil
		},
	)

	// Plan 005: party key rotation — party-authenticated (any currently-
	// valid key may sign, including grace-window keys); the handler
	// additionally enforces caller == path party.
	r.With(partyAuth).Post("/v1/parties/{id}/keys", partiesHandler.RotateKey)

	// Plan 006: party health probe — party-authenticated (PartyAuth), no
	// ownership check: any active registered party may probe any party.
	r.With(partyAuth).Get("/v1/parties/{id}/health", partiesHandler.Health)

	// Routes
	r.Get("/", apiDocsHandler)
	// Health accepts any method (r.Handle registers mALL): webhook delivery
	// and the sync forward are POST by contract, and the QC self-probe
	// webhook listing points its endpoint_url here — a GET-only route would
	// 405 every self-delivery.
	r.Handle("/health", http.HandlerFunc(deliveryhttp.HealthHandler))

	// Public routes
	r.Post("/v1/parties/register", partiesHandler.Register)

	// Plan 005: JWKS endpoints (public). Gateway JWKS serves the current
	// config key, kid derived as its RFC 7638 thumbprint.
	r.Get("/v1/parties/{id}/jwks", partyJWKSHandler.PartyJWKS)
	r.Get("/.well-known/jwks", gatewayJWKSHandler.GatewayJWKS)

	r.Post("/v1/identities/register", identitiesHandler.Register)
	r.Post("/v1/identities/resolve", identitiesHandler.Resolve)
	r.Post("/v1/identities/link", identitiesHandler.Link)
	r.Post("/v1/admin/auth/login", adminHandler.Login) // intentionally public — bootstraps the admin JWT

	// Marketplace catalog: party-authenticated enlist (invocation/price_scope
	// gating dimensions, plan 017), public trust-enriched read (tier/org).
	listingsService := listings.NewService(listingsRepo, partyRepo)
	listingsHandler := apphttp.NewListingsHandler(listingsService)
	r.With(partyAuth).Post("/v1/listings", listingsHandler.Create)
	r.Get("/v1/listings", listingsHandler.List)

	// Payment creation + owner-guarded status + plan-016 access-token mint.
	r.With(partyAuth).Post("/v1/payments", paymentsHandler.Create)
	r.With(partyAuth).Get("/v1/payments/{id}", paymentsHandler.GetByID)
	r.With(partyAuth).Post("/v1/payments/{id}/access-token", paymentsHandler.AccessToken)

	// Money plane: registered Xendit Payment Sessions webhook URL. Xendit
	// sends no Idempotency-Key header; the Idempotency middleware passes
	// header-less POSTs through untouched, and callback dedupe is the
	// service-level (payment_session_id, event) transition guard.
	r.Post("/v1/payments/callback", paymentsHandler.Callback)

	// Integration plane: marketplace-gated invocation (plan 007/017).
	// Static /v1/webhooks/dlq registers before the {id} wildcard (chi
	// prefers static segments regardless; the router test locks it).
	// Result callbacks carry EITHER a single-use result ticket (engine) or
	// the recipient's party JWT — resolved in the handler, so the route
	// runs without PartyAuth middleware.
	webhooksHandler := apphttp.NewWebhooksHandler(webhooksService, func(ctx context.Context, token string) (string, bool) {
		pid, storeErr, ok := middleware.VerifyPartyToken(ctx, token, keyLookup)
		return pid, ok && storeErr == nil
	})
	adminAuth := middleware.AdminAuth(adminPrivKey.Public().(ed25519.PublicKey))
	r.With(partyAuth).Post("/v1/webhooks", webhooksHandler.Enqueue)
	r.With(partyAuth).Post("/v1/webhooks/sync", webhooksHandler.Sync)
	r.With(adminAuth).Get("/v1/webhooks/dlq", webhooksHandler.DLQ)
	r.With(partyAuth).Get("/v1/webhooks/{id}/status", webhooksHandler.Status)
	r.Post("/v1/webhooks/{id}/result", webhooksHandler.Result)

	// Admin routes (protected — login is public, see above). Tier
	// management (plan 011 §5b): v1 exposes konsulin + authorized;
	// unofficial is reserved in the schema CHECK and rejected by handler.
	tierService := admin.NewTierService(partyRepo, auditRepo)
	tierHandler := apphttp.NewTierHandler(tierService)
	r.Route("/v1/admin", func(r chi.Router) {
		r.Use(adminAuth)
		r.Post("/tokens", adminHandler.CreateToken)
		r.Post("/parties/{id}/promote", adminHandler.Promote)
		r.Post("/parties/{id}/revoke", adminHandler.Revoke)
		r.Post("/parties/{id}/tier", tierHandler.SetTier)
	})

	return r, payments.NewSweeper(paymentsRepo, auditRepo, time.Minute), webhooksWorker, nil
}

// parseDur parses a config duration string, falling back on empty, invalid,
// or non-positive values (an unparseable optional never blocks boot).
func parseDur(raw string, fallback time.Duration) time.Duration {
	if d, err := time.ParseDuration(raw); err == nil && d > 0 {
		return d
	}
	return fallback
}

