	"github.com/konsulin-care/konsulin-gateway/internal/app/contracts"
	"github.com/konsulin-care/konsulin-gateway/internal/app/services/sts"
	gatewayerrors "github.com/konsulin-care/konsulin-gateway/pkg/errors"
)

// AccessTokenResult is the plan-016 mint response.
type AccessTokenResult struct {
	Token     string    `json:"access_token"`
	ExpiresAt time.Time `json:"expires_at"`
}

// AccessToken mints the direct-channel access ticket for a PAID listing
// payment (plan 016): caller must own the row (foreign/unknown -> 404, no
// existence disclosure); PENDING -> 403; the listing must still be active
// -> 404 otherwise. Ticket claims are gateway-derived — the buyer
// constructs none: aud=<provider>, sub=<buyer>, scope=listing:<id>,
// purpose=payment:<id>, exp ≤ 900s. The tickets store keeps the audit row.
func (s *Service) AccessToken(ctx context.Context, paymentID, callerPartyID string) (*AccessTokenResult, *gatewayerrors.DomainError) {
	if s.gatewayPriv == nil {
		return nil, failClosed("access token signing key unavailable")
	}

	row, err := s.payments.GetByID(ctx, paymentID)
	if err != nil {
		return nil, failClosed("payment lookup failed")
	}
	if row == nil || row.PartyID != callerPartyID {
		return nil, &gatewayerrors.DomainError{
			Code: gatewayerrors.CodeInvoiceNotFound, Message: "payment not found", HTTPStatus: 404,
		}
	}
	if row.Status != contracts.StatusPaid {
		return nil, &gatewayerrors.DomainError{
			Code: gatewayerrors.CodeApprovalRequired, Message: "payment not settled", HTTPStatus: 403,
		}
	}

	listing, err := s.listings.GetByID(ctx, row.ListingID)
	if err != nil {
		return nil, failClosed("listing lookup failed")
	}
	if listing == nil || listing.State != contracts.ListingStateActive {
		return nil, &gatewayerrors.DomainError{
			Code: gatewayerrors.CodeListingNotFound, Message: "listing not found or not active", HTTPStatus: 404,
		}
	}

	ticket, merr := sts.Mint(s.gatewayPriv, sts.Request{
		Aud:     listing.ProviderPartyID,
		Sub:     callerPartyID,
		Scope:   "listing:" + row.ListingID,
		Purpose: "payment:" + row.PaymentID,
		TTL:     sts.MaxTicketTTL,
	})
	if merr != nil {
		return nil, failClosed("access token mint failed")
	}

	if s.tickets != nil {
		now := time.Now().Unix()
		_ = s.tickets.Record(ctx, &contracts.Ticket{
			JTI: ticket.JTI, PartyID: callerPartyID, Aud: listing.ProviderPartyID,
			Scope: "listing-access", Purpose: row.PaymentID,
			Iat: now, Exp: now + int64(sts.MaxTicketTTL.Seconds()),
		})
	}

	s.logAudit(ctx, "access-token-minted", row.PaymentID, map[string]interface{}{
		"listing_id": row.ListingID, "provider": listing.ProviderPartyID,
		"buyer": callerPartyID,
	})
	return &AccessTokenResult{Token: ticket.Token, ExpiresAt: ticket.ExpiresAt}, nil
}

