// IdentityHash represents a party's hashed identity mapping under a shared
// global key. Email and phone are HMAC hashes computed party-side (ADR-005);
// the gateway only validates format and stores. The "N/A" marker denotes a
// not-applicable field.
type IdentityHash struct {
	PartyID         string
	ResourceType    string
	LocalResourceID string
	GlobalKey       string
	EmailHash       string
	PhoneHash       string
	CreatedAt       time.Time
}

// Link represents a declared equivalence between a global key and a party's
// local resource. Links heal identity fragmentation; they never auto-join
// clinical data.
type Link struct {
	GlobalKey       string
	PartyID         string
	LocalResourceID string
	LinkedBy        string
	LinkedAt        time.Time
}

// IdentityRepository manages identity hash persistence and dedup merging.
type IdentityRepository interface {
	// FindByHashes returns rows matching email_hash OR phone_hash.
	// The "N/A" marker never matches. OR semantics: a non-"N/A" argument
	// matches its column; "N/A" arguments are ignored for matching.
	FindByHashes(ctx context.Context, emailHash, phoneHash string) ([]*IdentityHash, error)
	// Upsert stores a row, updating hashes on conflict of the natural key
	// (party_id, resource_type, local_resource_id).
	Upsert(ctx context.Context, row *IdentityHash) error
	// ExistsByGlobalKey reports whether any row carries the given global key.
	ExistsByGlobalKey(ctx context.Context, globalKey string) (bool, error)
	// Rekey rewrites global_key from fromKeys to toKey across all rows.
	Rekey(ctx context.Context, fromKeys []string, toKey string) error
}

// LinkRepository manages equivalence link persistence.
type LinkRepository interface {
	// Create stores a new equivalence link.
	Create(ctx context.Context, link *Link) error
	// FindByGlobalKeys returns links sharing any of the given global keys.
	FindByGlobalKeys(ctx context.Context, keys []string) ([]*Link, error)
	// Rekey rewrites global_key from fromKeys to toKey across all links.
	Rekey(ctx context.Context, fromKeys []string, toKey string) error
}

